/*
 * Golden parity: the Swift FitnessBrainEngine must reproduce the web
 * engine's outputs exactly. Fixtures are generated by running the REAL
 * TypeScript engine (Tools/generate-parity-fixtures.mts); if the web brain
 * changes, regenerate and this suite tells you precisely where the Swift
 * port drifted.
 */
import XCTest
@testable import APEX

private struct Fixture: Decodable, Sendable {
    let generated_on: String
    let scenarios: [Scenario]
}

private struct Scenario: Decodable, Sendable {
    let name: String
    let through_date: String
    let input: Input
    let expected: Expected
}

private struct Input: Decodable, Sendable {
    let profile: FBProfile
    let settings_addons: Addons?
    let program_days: [FBProgramDayRef]
    let exercises: [FBExerciseRef]
    let workout_sessions: [FBWorkoutSession]
    let workout_logs: [FBWorkoutLog]
    let daily_logs: [FBDailyLog]
    let hydration_targets: [String: Int]?
    let health_metrics: [FBHealthMetric]
    let imported_activities: [FBImportedActivity]
    let fitness_evidence: [FitnessEvidenceRecord]?
}

private struct Addons: Decodable, Sendable {
    let recovery_history: [FBRecoveryCheckin]?
    let meal_rhythm_history: [String: FBMealRhythmDayRaw]?
}

private struct Expected: Decodable, Sendable {
    let targets: FBTargets
    let snapshot_count: Int
    let first_snapshot: FBSnapshot?
    let last_snapshot: FBSnapshot?
    let sampled_snapshots: [FBSnapshot]
    let synergies: [FBSynergyEvent]
}

final class FitnessBrainParityTests: XCTestCase {
    func testCoachPublicationKeepsUnknownAndObservedScoresDistinct() throws {
        let snapshot = FBSnapshot(date: "2026-11-01", overall: 51, health: 52, joint: 53, flexibility: 54,
                                  endurance: 55, strength: 56, strengthUpper: 57, strengthLower: 58)
        let row = try XCTUnwrap(FitnessBrainService.appSnapshots([snapshot], userID: UUID()).first)
        func payload(_ score: FBSnapshot?) throws -> [String: Any] {
            let bytes = try JSONEncoder().encode(AvatarScorePublication(row: row, verified: score))
            return try XCTUnwrap(JSONSerialization.jsonObject(with: bytes) as? [String: Any])
        }
        let pending = try payload(nil)
        XCTAssertTrue(pending["verified_avatar"] is NSNull)
        XCTAssertEqual(pending["overall"] as? Int, 51)
        let published = try XCTUnwrap(try payload(snapshot)["verified_avatar"] as? [String: Any])
        XCTAssertEqual(Set(published.keys), ["date", "overall", "health", "joint", "flexibility", "endurance", "strength", "strength_upper", "strength_lower"])
        XCTAssertEqual(published["strength_lower"] as? Int, 58)
    }

    func testAvatarOutboxKeepsOnlyLatestCoverageForOwnerAndDay() async throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("avatar-\(UUID())", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let store = OfflineStore(rootURL: directory)
        let owner = UUID()
        let score = FBSnapshot(date: "2026-11-01", overall: 51, health: 52, joint: 53, flexibility: 54,
                               endurance: 55, strength: 56, strengthUpper: 57, strengthLower: 58)
        let row = try XCTUnwrap(FitnessBrainService.appSnapshots([score], userID: owner).first)
        try await store.enqueueAvatarPublication(.init(row: row, verified: score), for: owner)
        try await store.enqueueAvatarPublication(.init(row: row, verified: nil), for: owner)
        let pending = try await store.pendingOperations(for: owner)
        XCTAssertEqual(pending.count, 1)
        let payload = try XCTUnwrap(pending.first?.payload)
        let encoded = try XCTUnwrap(JSONSerialization.jsonObject(with: payload) as? [String: Any])
        XCTAssertTrue(encoded["verified_avatar"] is NSNull)
    }

    private func performedWorkoutInput() -> FBEngineInput {
        let profile = FBProfile(
            userID: "77777777-aaaa-4bbb-8ccc-777777777777", persona: .constantine,
            sex: "male", weightKG: 80, bodyFatPct: 15, customBMR: nil,
            heightCM: 180, birthdate: "1990-01-01", activityLevel: .moderate,
            goal: .maintain, baselineDate: "2026-11-01")
        return FBEngineInput(
            profile: profile,
            programDays: [FBProgramDayRef(id: "custom-day", dayType: .custom)],
            workoutSessions: [FBWorkoutSession(
                id: "session", date: "2026-11-02", programDayID: "custom-day",
                isDeload: false, isEventRecovery: false, completed: true, qualityScore: 1)])
    }

    private func performedLog(_ movementID: String, reps: Int? = 10,
                              duration: Int? = nil, distance: Double? = nil) -> FBWorkoutLog {
        var log = FBWorkoutLog(
            id: "log", sessionID: "session", exerciseID: nil, exerciseName: "Untrusted label",
            weightKG: 80, skipped: false, overrideFlag: false,
            movementID: movementID, reps: reps, durationSeconds: duration, distanceMeters: distance)
        log.performedTypes = MovementTiming.performedWorkoutTypes(for: log)
        return log
    }

    func testStandardScoresStayPendingUntilEveryDomainHasEvidence() throws {
        var input = performedWorkoutInput()
        input.workoutSessions = []
        let empty = FitnessBrainEngine.compute(input, throughDate: "2026-12-01")
        XCTAssertTrue(empty.domainScores.isEmpty)
        XCTAssertTrue(empty.publishableSnapshots.isEmpty)
        XCTAssertEqual(empty.snapshots.first?.overall, empty.snapshots.last?.overall)
        input = performedWorkoutInput()
        input.workoutLogs = [performedLog("barbell_back_squat")]
        let lower = FitnessBrainEngine.compute(input, throughDate: "2026-12-01")
        XCTAssertEqual(lower.domainScores, ["lower": 51.4])
        XCTAssertTrue(lower.publishableSnapshots.isEmpty)
    }

    func testAllocatedStartShowsChosenScoresAndReplaysEditedHistoricalQuickLogs() throws {
        var input = performedWorkoutInput()
        let points = ["health": 0, "joint": 45, "flexibility": 50, "endurance": 65,
                      "strength_upper": 100, "strength_lower": 40]
        input.profile.avatarStartingPoints = points
        let day = "2026-11-02"
        let base = FitnessBrainEngine.compute(input, throughDate: day)
        XCTAssertEqual(base.domainScores, ["health": 0, "joint": 45, "flexibility": 50, "endurance": 65, "upper": 100, "lower": 40])
        XCTAssertEqual(base.publishableSnapshots.count, 2)
        input.profile.avatarStartingPoints?["health"] = 1
        XCTAssertTrue(FitnessBrainEngine.compute(input, throughDate: day).publishableSnapshots.isEmpty)
        input.profile.avatarStartingPoints = points
        input.workoutSessions[0].date = "2026-10-30"
        input.workoutLogs = [performedLog("barbell_back_squat")]
        let trained = FitnessBrainEngine.compute(input, throughDate: day)
        XCTAssertEqual(trained.publishableSnapshots.first?.date, "2026-10-30")
        XCTAssertGreaterThan(try XCTUnwrap(trained.domainScores["lower"]), 40)
        input.workoutLogs = [performedLog("cat_cow", reps: nil, duration: 120)]
        let edited = FitnessBrainEngine.compute(input, throughDate: day)
        XCTAssertEqual(edited.domainScores["lower"], 40)
        XCTAssertGreaterThan(try XCTUnwrap(edited.domainScores["flexibility"]), 50)
        input.workoutSessions.removeAll()
        XCTAssertEqual(FitnessBrainEngine.compute(input, throughDate: day).snapshots, base.snapshots)
    }

    func testChosenDayZeroKeepsStartingPointsWithOlderWearableHistory() {
        var input = performedWorkoutInput()
        input.profile.avatarStartingPoints = AvatarStartingPoints.balanced
        input.healthMetrics = [FBHealthMetric(date: "2026-10-24", vo2max: 60, restingHR: nil)]
        input.importedActivities = [FBImportedActivity(date: "2026-10-27", kind: .mobility, durationMin: 30)]
        let result = FitnessBrainEngine.compute(input, throughDate: input.profile.baselineDate)
        XCTAssertEqual(result.publishableSnapshots.first?.endurance, 50)
        XCTAssertEqual(result.publishableSnapshots.first?.flexibility, 50)
    }

    func testMissedWorkoutUsesOnlyExplicitSkipsAndBackfillReplacesTheLoss() throws {
        var input = performedWorkoutInput()
        input.profile.avatarStartingPoints = AvatarStartingPoints.balanced
        input.programDays.append(FBProgramDayRef(id: "lower-day", dayType: .legsA))
        let custom = input.workoutSessions[0]
        var missed = custom
        missed.id = "skipped-session"
        missed.programDayID = "lower-day"
        var skip = performedLog("barbell_back_squat")
        skip.sessionID = missed.id
        skip.skipped = true
        input.workoutSessions = [missed]
        input.workoutLogs = [skip, skip]
        func result() -> FBEngineResult { FitnessBrainEngine.compute(input, throughDate: "2026-11-03") }
        XCTAssertEqual(result().domainScores["lower"], 49)
        XCTAssertEqual(result().synergies.filter { $0.kind == .skippedSession }.count, 1)
        input.workoutSessions[0].completed = false
        XCTAssertEqual(result().domainScores["lower"], 50)
        input.workoutSessions[0] = missed
        input.workoutSessions.append(custom)
        input.workoutLogs.append(performedLog("barbell_back_squat"))
        let corrected = result()
        XCTAssertFalse(corrected.synergies.contains { $0.kind == .skippedSession })
        input.workoutSessions = [custom]
        XCTAssertEqual(corrected.snapshots, result().snapshots)
    }

    func testPartialIntakeAndPersonalWaterGoalsDetermineWhichSynergiesAppear() {
        var input = performedWorkoutInput()
        let day = "2026-11-02"
        input.dailyLogs = [FBDailyLog(date: day, kcal: 400, proteinG: 12, waterL: 1.7)]
        input.programDays[0].dayType = .t25
        func events(_ through: String) -> [FBSynergyKind] {
            FitnessBrainEngine.compute(input, throughDate: through).synergies.map(\.kind)
        }
        input.hydrationByDay[day] = (2_000, 2_000)
        XCTAssertTrue(events(day).contains(.hydrationEndurance))
        input.hydrationByDay[day] = (2_500, 3_500)
        XCTAssertFalse(events(day).contains(.hydrationEndurance))
        input.programDays[0].dayType = .legsA
        XCTAssertFalse(events(day).contains(.deficitStrength))
        XCTAssertFalse(events("2026-11-03").contains(.deficitStrength))
        input.mealRhythmHistory[day] = FBMealRhythmDayRaw(finalized: true, expectedMeals: 3,
            loggedMeals: 3, completionScore: 100, rhythmScore: 100, verdict: "complete_on_time")
        XCTAssertFalse(events(day).contains(.deficitStrength))
        XCTAssertTrue(events("2026-11-03").contains(.deficitStrength))
    }

    func testPerformedQuickLogsMatchWebNumericDomainCredit() throws {
        // Same inputs and exact expected values as rpg-performed-workout.test.ts.
        let empty = performedWorkoutInput()
        let before = try XCTUnwrap(FitnessBrainEngine.compute(empty, throughDate: "2026-11-02").snapshots.last)
        let cases: [(FBWorkoutLog, KeyPath<FBSnapshot, Double>, Double)] = [
            (performedLog("barbell_back_squat"), \.strengthLower, 51.4),
            (performedLog("push_up"), \.strengthUpper, 51.1),
            (performedLog("cat_cow", reps: nil, duration: 120), \.flexibility, 51.5),
            (performedLog("run_outdoor", reps: nil, duration: 1800, distance: 5000), \.endurance, 51.8),
        ]
        for (log, domain, expected) in cases {
            var input = empty
            input.workoutLogs = [log]
            let result = try XCTUnwrap(FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots.last)
            XCTAssertEqual(result[keyPath: domain], expected)
            for other in [\FBSnapshot.strengthLower, \.strengthUpper, \.flexibility, \.endurance] where other != domain {
                XCTAssertEqual(result[keyPath: other], before[keyPath: other])
            }
        }
    }

    func testQuickLogCreditRequiresKnownPerformedWorkAndIsBoundedPerDay() throws {
        let empty = performedWorkoutInput()
        let before = FitnessBrainEngine.compute(empty, throughDate: "2026-11-02").snapshots
        for log in [performedLog("unknown"), performedLog("barbell_back_squat", reps: 0)] {
            var input = empty
            input.workoutLogs = [log]
            XCTAssertEqual(FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots, before)
        }
        var input = empty
        input.workoutLogs = [performedLog("barbell_back_squat")]
        let once = FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots
        input.workoutLogs.append(input.workoutLogs[0])
        var another = input.workoutSessions[0]
        another.id = "other"
        input.workoutSessions.append(another)
        var anotherLog = input.workoutLogs[0]
        anotherLog.sessionID = "other"
        input.workoutLogs.append(anotherLog)
        XCTAssertEqual(FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots, once)
        input.workoutSessions = input.workoutSessions.map { var value = $0; value.completed = false; return value }
        XCTAssertEqual(FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots, before)
    }

    func testIncompleteOrSkippedLogsCannotAddOverloadOrOverridePenalty() {
        var input = performedWorkoutInput()
        input.programDays[0].dayType = .legsA
        input.exercises = [FBExerciseRef(id: "exercise", programDayID: "custom-day")]
        input.workoutSessions[0].date = "2026-11-01"
        var first = performedLog("barbell_back_squat")
        first.exerciseID = "exercise"
        first.weightKG = 60
        input.workoutLogs = [first]
        let before = FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots
        var pending = input.workoutSessions[0]
        pending.id = "pending"
        pending.date = "2026-11-02"
        pending.completed = false
        input.workoutSessions.append(pending)
        var heavier = first
        heavier.id = "heavier"
        heavier.sessionID = "pending"
        heavier.weightKG = 100
        heavier.overrideFlag = true
        input.workoutLogs.append(heavier)
        XCTAssertEqual(FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots, before)
        input.workoutSessions.removeLast()
        heavier.sessionID = "session"
        heavier.skipped = true
        input.workoutLogs = [first, heavier]
        XCTAssertEqual(FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots, before)
    }

    func testPlannedNoWorkAndZeroQualityDoNotEarnDomainCredit() {
        let empty = performedWorkoutInput()
        let baseline = FitnessBrainEngine.compute(empty, throughDate: "2026-11-02").snapshots
        var skipped = performedLog("barbell_back_squat")
        skipped.skipped = true
        for (log, quality) in [
            (skipped, 1.0),
            (performedLog("barbell_back_squat", reps: 0), 0.0),
            (performedLog("barbell_back_squat", reps: nil), 1.0),
            (performedLog("barbell_back_squat"), 0.0),
        ] {
            var input = empty
            input.programDays[0].dayType = .legsA
            input.workoutSessions[0].qualityScore = quality
            input.workoutLogs = [log]
            XCTAssertEqual(FitnessBrainEngine.compute(input, throughDate: "2026-11-02").snapshots, baseline)
        }
    }

