    func testMissingMealLogsAndDatedManualHealthCalibration() {
        var profile = bespokeProfile()
        profile.baselineDate = "2026-01-01"
        var input = FBEngineInput(profile: profile)
        let through = "2026-01-03"
        let unadjusted = FitnessBrainEngine.compute(input, throughDate: through).snapshots
        for verdict in ["no_meals", "missed_meals"] {
            input.mealRhythmHistory["2026-01-02"] = .init(finalized: true, expectedMeals: 3,
                loggedMeals: verdict == "no_meals" ? 0 : 1, completionScore: 0, rhythmScore: 0, verdict: verdict)
            XCTAssertEqual(FitnessBrainEngine.compute(input, throughDate: through).snapshots, unadjusted)
        }
        input.avatarCalibration = .init(date: "2026-01-02", score: 73, source: "manual")
        let result = FitnessBrainEngine.compute(input, throughDate: through)
        XCTAssertEqual(result.snapshots[0], unadjusted[0])
        XCTAssertEqual(result.snapshots[1].health, 73)
        XCTAssertEqual(result.snapshots[1].strength, unadjusted[1].strength)
        XCTAssertLessThan(result.snapshots[2].health, 73)
        XCTAssertEqual(result.synergies.filter { $0.kind == .manualHealthCalibration }.count, 1)
        input.avatarCalibration?.scores = .init(joint: 57, flexibility: 66, endurance: 52)
        let adjusted = FitnessBrainEngine.compute(input, throughDate: through).snapshots
        XCTAssertEqual(adjusted[0], unadjusted[0])
        XCTAssertEqual([adjusted[1].joint, adjusted[1].flexibility, adjusted[1].endurance, adjusted[1].health],
                       [57, 66, 52, 73])
        XCTAssertEqual(adjusted[1].strength, unadjusted[1].strength)
        XCTAssertLessThan(adjusted[2].flexibility, 66)
        input.profile.profileKind = "standard"
        XCTAssertNil(FitnessBrainEngine.compute(input, throughDate: through).domainScores["health"])
    }

    func testMalformedBespokeReferenceDataCannotExposeNonFiniteTargets() {
        let profile = bespokeProfile()
        let target = FitnessBrainTargets.computeTargets(profile, asOf: "2026-09-02")

        XCTAssertEqual(target.kcal, 2_450)
        XCTAssertEqual(target.tdee, 2_550)
        XCTAssertEqual(target.proteinG, 150)
        XCTAssertEqual(target.fatG, 75)
        XCTAssertEqual(target.carbsG, 293)
        XCTAssertTrue(target.bmrMifflin.isFinite)
        XCTAssertNil(target.bmrKatch)
        XCTAssertTrue(target.isPublishable)

        let malformedOptionalReference = FBTargets(
            bmrMifflin: 1_600,
            bmrKatch: .nan,
            tdee: 2_400,
            kcal: 2_200,
            proteinG: 150,
            fatG: 70,
            carbsG: 242,
            waterL: 2.75
        )
        XCTAssertFalse(malformedOptionalReference.isPublishable)
    }

    /* Date math must agree with date-fns for the ranges the engine replays */
    func testDateArithmetic() {
        XCTAssertEqual(FBDate.daysBetween("2026-06-01", "2026-08-10"), 70)
        XCTAssertEqual(FBDate.addDays("2026-06-01", 0), "2026-06-01")
        XCTAssertEqual(FBDate.addDays("2026-06-01", 30), "2026-07-01")
        XCTAssertEqual(FBDate.addDays("2026-06-01", -60), "2026-04-02")
        XCTAssertEqual(FBDate.addDays("2024-02-28", 1), "2024-02-29")
        XCTAssertEqual(FBDate.addDays("2026-12-31", 1), "2027-01-01")
        XCTAssertEqual(FitnessBrainTargets.ageFrom(birthdate: "1992-07-25", asOf: "2026-07-24"), 33)
        XCTAssertEqual(FitnessBrainTargets.ageFrom(birthdate: "1992-07-25", asOf: "2026-07-25"), 34)
    }
}
